abstract interface class Gateway {
  /// Calls [fetchToken] on the server.
  Future<String> fetchToken();
}

class HttpGateway implements Gateway {
  @override
  Future<String> fetchToken() async {
    return _send();
  }

  Future<String> _send() async => 'token';
}

class TokenRefresher {
  TokenRefresher(this.gateway);

  final Gateway gateway;

  Future<String> refresh() async {
    return gateway.fetchToken();
  }
}

class RetryInterceptor {
  RetryInterceptor(this.refresher);

  final TokenRefresher refresher;

  Future<String> onFailure() async {
    return refresher.refresh();
  }
}

class TokenWarmup {
  TokenWarmup(this.refresher);

  final TokenRefresher refresher;

  Future<String> warm() async {
    return refresher.refresh();
  }
}

class Named {
  const Named(this.name);

  final String name;
}

class GatewayModule {
  @Named('token')
  Gateway gateway() => HttpGateway();
}

import 'flow.dart';

class NamedUser {
  NamedUser({
    @Named('user') required this.user,
  });
  void greet() {}
  final String user;
}
